  const act = (aS+aS2)/8, inh = (iS+iS2)/8;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.035+t*1.0) + Math.sin(sx*0.05+sy*0.05-t*0.5)*0.5)/2.5;
  const bg2 = (Math.sin((sx+sy)*0.11+t*2.2)*0.3 + Math.sin((sx-sy)*0.09-t*1.8)*0.3 + Math.sin(sx*0.08+t*1.5)*Math.sin(sy*0.07-t*1.2)*0.4);
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.4) + Math.sin(dist*0.035+ang*4.5-t*1.1) + Math.sin(dist*0.06-ang*2-t*1.8)*0.5)*0.3;
  const voronoi = (p,q) => { let m=9e9, s=0; for(let i=0;i<8;i++){const px=80+i*50+Math.sin(t*0.3+i*1.7)*30, py=40+i*25+Math.cos(t*0.25+i*2.1)*20; const d=Math.sqrt((p-px)**2+(q-py)**2); if(d<m){m=d;s=i;} } return m; };
  const cellDist = voronoi(sx*0.12, sy*0.12);
  const cell = Math.tanh((Math.sin(cellDist*0.8-t*0.5)*0.6 + Math.sin(sx*0.14)*Math.sin(sy*0.14)*0.4)*2.0)*0.25;
  const rd1 = Math.tanh((act - inh*0.65 + bg*0.25 + spiral)*2.0);
