  const pal = [[5,12,52],[12,45,85],[18,95,115],[30,155,135],[160,195,80],[220,175,55],[195,90,65],[140,40,55],[65,18,45],[5,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
